  "scopeNoteEl": "Για το Ημερήσιο Γυμνάσιο χαρτογραφούνται 46 μαθήματα. Τα μαθήματα 4 και 5 παραλείπονται σύμφωνα με τις οδηγίες 2026–27. Το μάθημα 13 παραμένει διαθέσιμο αλλά σημειώνεται ως προαιρετικό, επειδή μπορεί να παραληφθεί κατά την κρίση του/της εκπαιδευτικού.",
  "scopeNoteEn": "For day-school Gymnasium, 46 lessons are mapped. Lessons 4 and 5 are omitted by the 2026–27 guidance. Lesson 13 remains available but is marked optional because the teacher may omit it.",
